import {zipSync,unzipSync,strToU8,strFromU8} from './vendor/fflate.js';
import {escapeHTML as esc,normalize,safeImage,safeURL,uid} from './domain.js';
export function markdown(doc){return `# ${doc.title}\n\n`+doc.steps.map((s,i)=>`## ${i+1}. ${s.title}\n\n${s.description||''}\n${s.url?`\nSource: ${safeURL(s.url)}\n`:''}`).join('\n')}
export function html(doc){return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(doc.title)}</title><style>body{font:18px system-ui;max-width:900px;margin:40px auto;padding:20px;line-height:1.6}img{max-width:100%}section{break-inside:avoid;margin:40px 0}p{white-space:pre-wrap}</style><h1>${esc(doc.title)}</h1>${doc.steps.map((s,i)=>`<section><h2>${i+1}. ${esc(s.title)}</h2>${safeImage(s.screenshot)?`<img src="${safeImage(s.screenshot)}" alt="${esc(s.alt||s.title)}">`:''}<p>${esc(s.description)}</p>${safeURL(s.url)?`<a href="${safeURL(s.url)}" rel="noreferrer">Source page</a>`:''}</section>`).join('')}</html>`}
export function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
export function exportZip(doc,includeOriginals=false){const out=structuredClone(doc);if(!includeOriginals)for(const s of out.steps){delete s.original;delete s.imageHistory;}const files={'manifest.json':strToU8(JSON.stringify({format:'pathira',version:2,guideId:doc.id,originals:includeOriginals,exportedAt:new Date().toISOString()})),'guide.json':strToU8(JSON.stringify(out,null,2)),'guide.md':strToU8(markdown(out)),'guide.html':strToU8(html(out))};for(const [i,s]of out.steps.entries())for(const field of ['screenshot','original'])if(s[field]?.startsWith('data:image/'))files[`images/${i+1}-${field}.${s[field].includes('image/png')?'png':'jpg'}`]=Uint8Array.from(atob(s[field].split(',')[1]),c=>c.charCodeAt(0));return zipSync(files)}
export async function importZip(file,workspaceId){if(file.size>100*1024*1024)throw Error('Project exceeds 100 MB');const entries=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:file=>['manifest.json','guide.json'].includes(file.name)&&file.originalSize<100*1024*1024});if(!entries['guide.json']||!entries['manifest.json'])throw Error('Not a Pathira project ZIP');const manifest=JSON.parse(strFromU8(entries['manifest.json']));if(manifest.format!=='pathira')throw Error('Unknown project format');const doc=normalize(JSON.parse(strFromU8(entries['guide.json'])),workspaceId);doc.id=uid();doc.revision=0;doc.dirty=true;doc.title+=' (imported)';return doc}
